const j = $('When Called').first().json || {};
const person = {};
const full = String(j.name || '').trim();
if (full) {
  const parts = full.split(/\s+/);
  const given = parts.shift();
  const family = parts.join(' ');
  const nm = { givenName: given };
  if (family) nm.familyName = family;
  person.names = [nm];
}
const email = String(j.email || '').trim();
if (email) person.emailAddresses = [{ value: email }];
const phone = String(j.phone || '').trim();
if (phone) person.phoneNumbers = [{ value: phone }];
const org = String(j.organization || '').trim();
const title = String(j.title || '').trim();
if (org || title) { const o = {}; if (org) o.name = org; if (title) o.title = title; person.organizations = [o]; }
const website = String(j.website || '').trim();
if (website) person.urls = [{ value: website }];
return [{ json: { body: person } }];

const p = $input.first().json || {};
const name = ((p.names || [])[0] || {}).displayName || null;
const email = ((p.emailAddresses || [])[0] || {}).value || null;
const phone = ((p.phoneNumbers || [])[0] || {}).value || null;
const website = ((p.urls || [])[0] || {}).value || null;
const err = p.error ? (p.error.message || JSON.stringify(p.error)) : null;
return [{ json: {
  ok: !!p.resourceName && !err,
  resourceName: p.resourceName || null,
  name, email, phone, website,
  error: err
} }];
